import{_ as t,l,o as a,c as o,v as r,p as s,x as i,d as p,i as m,S as c}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"最优所得税","description":"","frontmatter":{"title":"最优所得税","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mirrlees-income.md","filePath":"econ/mirrlees-income.md","lastUpdated":1789023840000}'),d={name:"econ/mirrlees-income.md"};function E(h,e,A,T,B,_){const n=l("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="最优所得税" tabindex="-1">最优所得税 <a class="header-anchor" href="#最优所得税" aria-label="Permalink to &quot;最优所得税&quot;">​</a></h1><div class="epigraph"><p>技能不可观察时，只能对收入课非线性税；激励相容把高技能的信息租金留下，最优边际税率在顶上为零。</p><footer>—— Mirrlees, An Exploration in the Theory of Optimum Income Taxation, Review of Economic Studies, 1971</footer></div><p><a href="/econ/diamond-mirrlees">上一课</a>（Diamond–Mirrlees 生产效率）。生产侧保持有效，扭曲留给最终消费。本课不重写中间品不征。缺口是劳动：技能 \\(n\\) 是私有信息，计划者看见的是收入 \\(y=n\\ell\\)，不是 \\(\\ell\\) 本身。一次总付对 \\(n\\) 做不到，Ramsey 商品税也只是粗工具。Mirrlees 用非线性 \\(T(y)\\) 在激励相容下再分配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续类型 \\(n\\)，效用 \\(u(c,\\ell)\\)，\\(c=y-T(y)\\)。个人选劳动使税后最优。计划者最大化加权福利，约束是资源与激励相容（高 \\(n\\) 不愿假装成低 \\(n\\)）。IC 的一阶形式是包络：信息租金随 \\(n\\) 积出来，再分配必须留给高技能足够的剩余，否则他们减劳动。缺口不是再写 Ramsey 逆弹性，而是：<strong>非线性所得税怎样把「对技能的总额税」换成「对收入的扭曲」，以及边际税 \\(T&#39;(y)\\) 在两端的形状。</strong></p><p>顶上无扭曲：最高 \\(n\\) 没有人要与他分离，再征边际税只减他的劳动、不改善任何人的 IC，故 \\(T&#39;(y_{\\max})=0\\)。底端与中间：正边际税用来减少高类型向下模仿的吸引力，并筹再分配。</p><h3 id="非线性税不是-ramsey-的另一张表" tabindex="-1">非线性税不是 Ramsey 的另一张表 <a class="header-anchor" href="#非线性税不是-ramsey-的另一张表" aria-label="Permalink to &quot;非线性税不是 Ramsey 的另一张表&quot;">​</a></h3><p>Ramsey 对观察得到的商品钉线性楔。Mirrlees 对观察得到的收入钉整条 \\(T(\\cdot)\\)。Atkinson–Stiglitz：若 \\(c\\) 与闲暇弱可分，商品税多余，只留所得税——上一课 Ramsey 边界已点过，本课把它认作工具分工。技能分布、社会福利权，决定中间段 \\(T&#39;\\) 的高低，没有一张永恒的「最优税率 20%」。</p><p><span class="marginnote">Mirrlees 1971 的数值例子对当时的英国校准，中间边际税可以相当高；「顶上为零」是理论边界，不是说最高收入档法定税率应为零——若 \\(n\\) 无上界，末端条件改写成渐近。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制设计：直接机制报类型，显示原理给出 \\(c(n),y(n)\\)，再实现为 \\(T(y)\\)。一阶 IC：\\(\\frac{\\mathrm{d}}{\\mathrm{d}n}u=\\frac{\\partial u}{\\partial n}\\) 沿真实类型。资源：\\(\\int c\\le\\int y\\)（加上政府外生支出）。福利权与技能密度进入「虚拟社会价值」，最优 \\(T&#39;(y)\\) 随该虚拟价值与劳动供给弹性变——Saez 后来写成弹性形式，本课只钉 Mirrlees 的 IC 结构。</p><p>Bunching：若虚拟价值在某段不单调，最优会把一段 \\(n\\) 压到同一 \\(y\\)，边际税率跳。这是角点，不是计算错误。底端参与约束还可以给出正的平均税、零附近的边际形态，视是否工作这一档的劳动供给而定。</p>',12)),(a(),s(c,null,{default:i(()=>[m(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%94%9F%E4%BA%A7%E6%9C%89%E6%95%88%EF%BC%8C%E6%89%AD%E6%9B%B2%E5%9C%A8%E6%B6%88%E8%B4%B9%22%5D%20--%3E%20SK%5B%22%E6%8A%80%E8%83%BD%20n%20%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%0A%20%20SK%20--%3E%20IC%5B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%20T(y)%20%2B%20%E6%BF%80%E5%8A%B1%E7%9B%B8%E5%AE%B9%22%5D%0A%20%20IC%20--%3E%20TOP%5B%22%E9%A1%B6%E7%AB%AF%20T'%20%3D%200%22%5D%0A%20%20IC%20--%3E%20RENT%5B%22%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E9%9A%8F%20n%20%E7%A7%AF%E5%87%BA%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>本课仍假定生产有效那一套 \\(p\\) 在。所得税扭曲的是劳动–消费，不回头去征中间品。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IC 的机制是单交叉：高技能装低技能更轻松，必须让 \\(y(n)\\) 递增，并用 \\(c(n)\\) 的斜率把模仿的边际利益抵消。扭曲劳动的机制是：降低低档的边际净工资，使高类型觉得「假装低档」更不划算。顶上无扭曲的机制是：没有更高类型需要被阻止模仿他。</p><p>与总额税的对照：若 \\(n\\) 可见，对每个 \\(n\\) 征不同 lump-sum，劳动不扭曲，回到第二定理。不可见则信息租金是再分配的代价，最优接受一段 \\(T&#39;\\gt 0\\)。</p><p>弹性形式（后来的写法）：\\(T&#39;/(1-T&#39;)\\) 与「再分配的社会价值」成正比，与劳动供给弹性成反比——Ramsey 逆弹性在技能维度上的亲戚。本课不把公式当成税率表：分布在顶上很厚时，顶上为零只是最后一个人的性质，接近顶端的 \\(T&#39;\\) 仍可高。</p><p><span class="marginnote">显示原理把「任意税制」收成直接机制；谎报工资、逃税、家庭联合申报，都会改观察变量，最优 \\(T\\) 跟着改。主干停在 \\(y\\) 可验证、\\(\\ell\\) 不可见。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>技能与偏好同时异质时，还要防偏好伪装，最优 \\(T\\) 更脆。</p><p>动态、资本收入、人力资本投资，把 Mirrlees 静态技能模型打开，不在本课。逃税把观察变量从 \\(y\\) 换成申报，最优要叠稽查。政治约束「边际税率不能下降」本身是额外 \\(g(x)\\)。下一课<a href="/econ/arrow-impossibility">阿罗</a>已经写过：这里用的福利权是人际比较，不是序数加总的免费 \\(W\\)。市场失灵课序在投票规则上收束。</p><p>后课默认：技能私有时最优工具是非线性 \\(T(y)\\)；IC 留下信息租金；有界最高技能处边际税为零；生产效率上一课仍适用。</p><p>本课不把顶上为零写成法定最高档税率为零。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>看不见 \\(n\\)，只能对 \\(y\\) 课税，并受激励相容约束。</li><li>再分配以信息租金与劳动扭曲为代价。</li><li>最高类型边际税为零；中间段由虚拟价值与弹性决定。</li><li>可分偏好下商品税可让位给所得税。</li><li>出处：Mirrlees, <em>RES</em>, 1971。</li></ul>',13))])}const f=t(d,[["render",E]]);export{y as __pageData,f as default};
